const float circle = std::numeric_limits<float>::pi() * 2.0f;
const float partition_step = circle / (num_buckets * partitions_per_bucket);
std::unique_ptr<std::map<float, std::vector<BucketPtr>>> partition_map =
    std::make_unique<std::map<float, std::vector<BucketPtr>>>();

// Create buckets and initialize
buckets_out.clear();
buckets_out.reserve(num_buckets);
for (int i = 0; i < num_buckets; ++i) {
    buckets_out.emplace_back(std::make_unique<Bucket>());
}

// Assign partitions to buckets
for (int bucket_idx = 0; bucket_idx < num_buckets; ++bucket_idx) {
    float start_angle = bucket_idx * partitions_per_bucket * partition_step;
    for (int part = 0; part < partitions_per_bucket; ++part) {
        float angle = start_angle + part * partition_step;
        partition_map->emplace(angle, std::vector<BucketPtr>());
    }
}

// Distribute buckets to partitions (uniformly)
for (int bucket_idx = 0; bucket_idx < num_buckets; ++bucket_idx) {
    float start_angle = bucket_idx * partitions_per_bucket * partition_step;
    for (int part = 0; part < partitions_per_bucket; ++part) {
        float angle = start_angle + part * partition_step;
        auto& bucket_list = partition_map->at(angle);
        bucket_list.push_back(buckets_out[bucket_idx]);
    }
}

// Create final map with equidistant partition points
auto result_map = std::make_unique<std::map<float, BucketPtr>>();
for (const auto& [angle, bucket_list] : *partition_map) {
    // For balanced view, we'll use the first bucket in each partition
    // (or could implement more sophisticated balancing)
    result_map->emplace(angle, bucket_list[0]);
}

return result_map;
// END_CODE

